// /frontend-react/src/components/TransportStatus.js (i18n Enabled)

import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next'; // 1. Import useTranslation
import HeaderBar from './HeaderBar';

// --- LOCAL MOCK DATA (remains the same) ---
const mockDriverInfo = {
    name: 'Sarah K.',
    carType: 'Blue Minivan',
    carColor: 'Blue',
    licensePlate: 'ABC 1234',
};

// Mock user's specific need
const mockTransportNeed = 'wheelchair'; 

// 2. Translate the labels in the mapping object using a function scope or hook
const TransportStatus = ({ isEasyMode, goToMedicalDashboard, goToAppointmentFlow, onMenuClick }) => {
    // 3. Initialize translation hook
    const { t } = useTranslation();
    
    // Define NEED_EMOJIS inside the component to use the t function
    const NEED_EMOJIS = {
        wheelchair: { emoji: '♿', label: t('transport_needs.chair') },
        bedridden: { emoji: '🛏️', label: t('transport_needs.bed') },
        slow: { emoji: '🚶', label: t('transport_needs.slow') },
    };

    const driverInfo = mockDriverInfo; 

    if (!driverInfo) {
        // 4. Translate the loading message
        return <h2 style={{fontSize: isEasyMode ? '48px' : '24px', textAlign: 'center'}}>{t('general.loading_transport_info')}</h2>;
    }

    // Default to 'Unknown' need if key is missing (ensure 'Unknown' is also translatable)
    const currentNeed = NEED_EMOJIS[mockTransportNeed] || { emoji: '❓', label: t('transport.unknown_need') };

    const CardStyle = {
        backgroundColor: '#fff',
        padding: '20px',
        borderRadius: '10px',
        margin: '20px 0',
        boxShadow: '0 4px 10px rgba(0,0,0,0.1)',
        borderLeft: '5px solid #1A73E8', 
    };

    return (
        <div style={{ padding: '0 20px 20px 20px', textAlign: 'center' }}>
            
            <HeaderBar 
                // 5. Translate the header title
                title={t('header.title_ride_status')} 
                onBackClick={goToMedicalDashboard} 
                onMenuClick={onMenuClick}
                isEasyMode={isEasyMode}
            />
            
            {/* 1. Transport Needs Card */}
            <div style={{...CardStyle, borderLeft: '5px solid orange', marginTop: '20px'}}>
                <p style={{fontSize: isEasyMode ? '32px' : '20px', fontWeight: 'bold', margin: '0 0 10px 0', color: '#555'}}>
                    {/* 6. Translate the booked need header */}
                    {t('transport.ride_status_header_booked')}
                </p>
                <span role="img" aria-label={currentNeed.label} style={{fontSize: isEasyMode ? '90px' : '50px', display: 'block'}}>
                    {currentNeed.emoji}
                </span>
                <p style={{fontSize: isEasyMode ? '28px' : '18px', margin: '5px 0', fontWeight: 'bold', color: 'orange'}}>
                    {currentNeed.label}
                </p>
                <button 
                    onClick={goToAppointmentFlow}
                    style={{ padding: '10px 20px', fontSize: isEasyMode ? '24px' : '16px', backgroundColor: 'orange', color: 'white', border: 'none', borderRadius: '8px', marginTop: '10px', fontWeight: 'bold' }}
                >
                    <span role="img" aria-label={t('general.edit')}>🔄</span> 
                    {/* 7. Translate the change need button */}
                    {t('general.change_need')}
                </button>
            </div>
            
            {/* 2. Driver Info Card */}
            <div style={{...CardStyle, borderLeft: '5px solid #4CAF50'}}> 
                <h3 style={{fontSize: isEasyMode ? '32px' : '24px', margin: '0 0 20px 0', color: '#4CAF50'}}>
                    {/* 8. Translate the driver header */}
                    {t('transport.driver_assigned_header')}
                </h3>

                <div style={{ display: 'flex', justifyContent: 'space-around', alignItems: 'center' }}>
                    
                    {/* Driver Details */}
                    <div style={{ textAlign: 'left', fontSize: isEasyMode ? '26px' : '16px' }}>
                        {/* 9. Translate all driver details labels */}
                        <p style={{margin: '5px 0'}}>{t('transport.driver_name_label')} **{driverInfo.name}**</p>
                        <p style={{margin: '5px 0'}}>{t('transport.driver_type_label')} **{driverInfo.carType}**</p>
                        <p style={{margin: '5px 0'}}>{t('transport.driver_color_label')} **{driverInfo.carColor}**</p>
                        <p style={{margin: '5px 0'}}>{t('transport.driver_plate_label')} **{driverInfo.licensePlate}**</p>
                    </div>

                    {/* Driver Photo/Icon */}
                    <span role="img" aria-label={t('transport.driver_aria_label')} style={{fontSize: isEasyMode ? '100px' : '50px'}}>🧑‍✈️</span>
                </div>
            </div>

            {/* 3. Back Button (bottom action) */}
            <button 
                onClick={goToMedicalDashboard} 
                style={{ 
                    marginTop: '30px', 
                    padding: '15px 40px', 
                    fontSize: isEasyMode ? '30px' : '18px',
                    backgroundColor: '#333',
                    color: 'white',
                    border: 'none',
                    borderRadius: '10px',
                    fontWeight: 'bold'
                }}
            >
                {/* 10. Translate the back button text and ARIA label */}
                <span role="img" aria-label={t('general.back')}>⬅️</span> {t('transport.back_to_menu')}
            </button>
        </div>
    );
}

export default TransportStatus;
